layer.onloaded:
js(
            var params = new URLSearchParams(location.search);
            var id = params.get('id') || 'alcazar_arquitectonico';

            if (!/^[A-Za-z0-9_-]+$/.test(id)) {
                console.error('Invalid id');
                return;
            }

            var url = 'https://artikel.elastichq.org/files/test/' + id + '.html';

            fetch(url)
                .then(function(r) {
                    if (!r.ok) throw new Error('HTTP ' + r.status);
                    return r.text();
                })
                .then(function(html) {
                    console.log('Loaded:', url);

                    var box = document.getElementById('external-content');
                    if (box) {
                        box.textContent = html;
                    }
                })
                .catch(function(err) {
                    console.error('Load failed:', err);
                });
        );
